import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for fused depthwise and pointwise convolution
fused_conv_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_depthwise_pointwise_kernel(
    const float* input,
    const float* depthwise_weight,
    const float* pointwise_weight,
    const float* combined_bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int n = blockIdx.z / out_channels;
    int c_out = blockIdx.z % out_channels;
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (n >= batch_size || c_out >= out_channels || h_out >= output_height || w_out >= output_width) {
        return;
    }

    float sum = 0.0f;

    for (int c_in = 0; c_in < in_channels; ++c_in) {
        float depth_sum = 0.0f;
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h_in = h_out * stride - padding + kh * dilation;
                int w_in = w_out * stride - padding + kw * dilation;
                if (h_in >= 0 && h_in < input_height && w_in >= 0 && w_in < input_width) {
                    int input_idx = n * in_channels * input_height * input_width + c_in * input_height * input_width + h_in * input_width + w_in;
                    int weight_idx = c_in * kernel_size * kernel_size + kh * kernel_size + kw;
                    depth_sum += input[input_idx] * depthwise_weight[weight_idx];
                }
            }
        }
        sum += depth_sum * pointwise_weight[c_out * in_channels + c_in];
    }

    if (combined_bias != nullptr) {
        sum += combined_bias[c_out];
    }

    int output_idx = n * out_channels * output_height * output_width + c_out * output_height * output_width + h_out * output_width + w_out;
    output[output_idx] = sum;
}

torch::Tensor fused_conv_forward(
    torch::Tensor input,
    torch::Tensor depthwise_weight,
    torch::Tensor pointwise_weight,
    torch::Tensor combined_bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_height = input.size(2);
    int input_width = input.size(3);
    int out_channels = pointwise_weight.size(0);

    int output_height = (input_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_width = (input_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, output_height, output_width}, input.options());

    dim3 block(16, 16);
    int grid_z = batch_size * out_channels;
    dim3 grid(
        (output_width + block.x - 1) / block.x,
        (output_height + block.y - 1) / block.y,
        grid_z
    );

    fused_depthwise_pointwise_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        depthwise_weight.data_ptr<float>(),
        pointwise_weight.data_ptr<float>(),
        combined_bias.defined() ? combined_bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_height,
        input_width,
        output_height,
        output_width,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

fused_conv_cpp_source = """
torch::Tensor fused_conv_forward(
    torch::Tensor input,
    torch::Tensor depthwise_weight,
    torch::Tensor pointwise_weight,
    torch::Tensor combined_bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation
);
"""

# Load the CUDA kernel
fused_conv = load_inline(
    name='fused_conv',
    cpp_sources=fused_conv_cpp_source,
    cuda_sources=fused_conv_source,
    functions=['fused_conv_forward'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.bias = bias

        self.depthwise_weight = nn.Parameter(torch.Tensor(in_channels, 1, kernel_size, kernel_size))
        self.pointwise_weight = nn.Parameter(torch.Tensor(out_channels, in_channels, 1, 1))

        if bias:
            self.depthwise_bias = nn.Parameter(torch.Tensor(in_channels))
            self.pointwise_bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('depthwise_bias', None)
            self.register_parameter('pointwise_bias', None)

        nn.init.kaiming_uniform_(self.depthwise_weight, a=math.sqrt(5))
        nn.init.kaiming_uniform_(self.pointwise_weight, a=math.sqrt(5))
        if bias:
            fan_in_depthwise, _ = nn.init._calculate_fan_in_and_fan_out(self.depthwise_weight)
            bound = 1 / math.sqrt(fan_in_depthwise)
            nn.init.uniform_(self.depthwise_bias, -bound, bound)
            fan_in_pointwise, _ = nn.init._calculate_fan_in_and_fan_out(self.pointwise_weight)
            bound = 1 / math.sqrt(fan_in_pointwise)
            nn.init.uniform_(self.pointwise_bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        combined_bias = None
        if self.bias:
            combined_bias = torch.mm(
                self.pointwise_weight.squeeze(-1).squeeze(-1),
                self.depthwise_bias.unsqueeze(1)
            ).squeeze(1) + self.pointwise_bias

        return fused_conv.fused_conv_forward(
            x,
            self.depthwise_weight,
            self.pointwise_weight,
            combined_bias if self.bias else torch.tensor([]).to(x.device),
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        )
